            //
            aOrbiterK = ((aOrbiterK + aOrbiterI) + 0xCA404A030629642BULL) + aSeedOrbiterUpdateSaltC[((aIndex + 21U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterK) ^ 0x81348BFBC9AC584EULL;
            aOrbiterA = RotL64((aOrbiterA * 0x2F30C1C1DE3EB5DFULL), 11U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterC) + 0x3DBAD86B2E6D7289ULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterJ) ^ 0x3B9F9C34DC2B5F74ULL) ^ aNonceWordN;
            aOrbiterE = RotL64((aOrbiterE * 0xCB54C4588D3A23B9ULL), 51U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterK) + 0x2B3488958509B092ULL) + aSeedOrbiterUpdateSaltF[(((31U - aIndex) + 6U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterG) ^ 0x9CE3B139D3078A3CULL;
