            aOrbiterC = (((aWandererB + RotL64(aIngress, 39U)) + RotL64(aCarry, 57U)) + 0x63CE8E8EDD86659FULL) + aTwistOrbiterAssignSaltD[(((31U - aIndex) + 13U)) & S_SALT1];
            //
            aOrbiterA = (aOrbiterA + aOrbiterE) + 0xB07E1FCD8465B0E4ULL;
