            aOrbiterA = ((aWandererD + RotL64(aScatter, 11U)) + RotL64(aCarry, 23U)) + 0x4D0ECA921BE16ADDULL;
            aOrbiterC = ((aWandererJ + RotL64(aCross, 53U)) + RotL64(aCarry, 57U)) + 0x10D12F26186DF729ULL;
            aOrbiterK = (((aWandererI + RotL64(aIngress, 27U)) + RotL64(aCarry, 5U)) + 0x18BF79A82ABF89C9ULL) + aTwistOrbiterAssignSaltF[(((31U - aIndex) + 26U)) & S_SALT1];
            aOrbiterJ = (aWandererE + RotL64(aPrevious, 41U)) + 0x894C9057733543A6ULL;
            aOrbiterH = ((aWandererF + RotL64(aCross, 60U)) + 0x22D1889FBF7C0997ULL) + aTwistOrbiterAssignSaltC[((aIndex + 17U)) & S_SALT1];
            aOrbiterG = (aWandererC + RotL64(aIngress, 19U)) + 0x8820F125E099AE99ULL;
            aOrbiterD = (aWandererG + RotL64(aPrevious, 3U)) + 0x9202D98EFB5023E5ULL;
