            aOrbiterB = (((aWandererG + RotL64(aPrevious, 29U)) + RotL64(aCarry, 23U)) + 0xD86DF882C78348AFULL) + aTwistOrbiterAssignSaltE[(((31U - aIndex) + 22U)) & S_SALT1];
