            //
            aOrbiterB = (aOrbiterB + aOrbiterI) + 0xA7049ED1F0612B27ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterB) ^ 0x930B324A21EC4968ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x6EAB933677883763ULL), 39U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterF) + 0x15D74C5A65308DE9ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterD) ^ 0x9377CD64EF58B6FCULL;
            aOrbiterB = RotL64((aOrbiterB * 0xC7A8EB139662D935ULL), 19U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterK) + 0x8C4D9A49F20EE619ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterA) ^ 0x37C7DBE3B8211C50ULL;
            aOrbiterD = RotL64((aOrbiterD * 0xEBAEF5B11B3637F7ULL), 37U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterA) + 0x065E81BA6AED8B84ULL;
