            aOrbiterC = RotL64((aOrbiterC * 0x39A38A4A1AB039C3ULL), 41U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterB) + 0x798F3D523987B183ULL) + aTwistOrbiterUpdateSaltC[((aIndex + 15U)) & S_SALT1];
            aOrbiterE = ((aOrbiterE ^ aOrbiterG) ^ 0xABEC13E5A2D7E22DULL) ^ aTwistOrbiterUpdateSaltA[((aIndex + 17U)) & S_SALT1];
