            aCross = (RotL64(aSoilLaneC[((S_BLOCK1 - aIndex + 3994U)) & S_BLOCK1], 37U) ^ RotL64(aSoilLaneD[((S_BLOCK1 - aIndex + 455U)) & S_BLOCK1], 19U));
