            //
            aOrbiterA = (aWandererD + RotL64(aPrevious, 57U)) + 0xC2D7CC0CA6CD7EDCULL;
            aOrbiterB = ((aWandererJ + RotL64(aCross, 22U)) + RotL64(aCarry, 29U)) + 0x428DD6E7E6BD11CEULL;
            aOrbiterF = ((aWandererK + RotL64(aIngress, 47U)) + 0xB66475C26E8AEC3DULL) + aTwistOrbiterAssignSaltA[((aIndex + 5U)) & S_SALT1];
