            //
            aIngress = (RotL64(aIceLaneA[((aIndex + 950U)) & S_BLOCK1], 51U) ^ RotL64(aIceLaneB[((aIndex + 1622U)) & S_BLOCK1], 26U));
            aIngress ^= (RotL64(aSoilLaneD[((aIndex + 6494U)) & S_BLOCK1], 3U) ^ RotL64(aLightningLaneA[((S_BLOCK1 - aIndex + 7914U)) & S_BLOCK1], 41U));
