            aCross ^= (RotL64(aLightningLaneC[((S_BLOCK1 - aIndex + 5369U)) & S_BLOCK1], 37U) ^ RotL64(aSoilLaneB[((S_BLOCK1 - aIndex + 5525U)) & S_BLOCK1], 5U));
