            aOrbiterF = (((aWandererE + RotL64(aCross, 27U)) + RotL64(aCarry, 5U)) + 0x87DBCFCEA354D9FBULL) + aTwistOrbiterAssignSaltB[(((31U - aIndex) + 25U)) & S_SALT1];
