            //
            aWandererC = aWandererC ^ ((RotL64(aCross, 57U) + RotL64(aOrbiterH, 30U)) + aOrbiterI);
            aWandererI = aWandererI + ((RotL64(aIngress, 53U) + RotL64(aOrbiterA, 19U)) + aOrbiterJ);
