            aWandererA = aWandererA + (((RotL64(aScatter, 12U) + aOrbiterH) + RotL64(aOrbiterG, 21U)) + aTwistWandererUpdateSaltC[((aIndex + 29U)) & S_SALT1]);
            aWandererJ = aWandererJ ^ ((RotL64(aPrevious, 19U) + aOrbiterK) + RotL64(aOrbiterE, 23U));
