            aCross ^= (RotL64(aKeyRowReadB[(((2047U - aIndex) + 13248U)) & W_KEY1], 52U) ^ RotL64(aHeartLaneC[((aIndex + 12145U)) & S_BLOCK1], 13U));
            aCross = TwistMix64::DiffuseC(aCross);
            //
            aScatter = (RotL64(aIngress, 5U) ^ RotL64(aCarry, 39U)) ^ (RotL64(aCross, 56U) + RotL64(aPrevious, 21U));
            aScatter = TwistMix64::DiffuseC(aScatter);
