            aOrbiterD = (aWandererA + RotL64(aScatter, 41U)) + 0xFDB3A910E47695CCULL;
            aOrbiterJ = (aWandererH + RotL64(aPrevious, 39U)) + 0x7D14B3739A7EF177ULL;
