            aOrbiterF = ((aWandererH + RotL64(aPrevious, 57U)) + RotL64(aCarry, 53U)) + 0xD7B9077483EE12C7ULL;
            aOrbiterB = ((aWandererI + RotL64(aIngress, 5U)) + RotL64(aCarry, 5U)) + 0x942A790C2CFD99E4ULL;
            aOrbiterA = ((aWandererK + RotL64(aCross, 35U)) + 0xFD2990DC208A2DD8ULL) + aTwistOrbiterAssignSaltB[((aIndex + 8U)) & S_SALT1];
            aOrbiterJ = (aWandererA + RotL64(aScatter, 46U)) + 0x84DE3AF86EE83C1DULL;
            aOrbiterH = (aWandererF + RotL64(aCross, 29U)) + 0x441DEC1AAE3F298EULL;
            aOrbiterC = (aWandererG + RotL64(aPrevious, 13U)) + 0xC722C29662898633ULL;
            //
