            aIngress = aIngress + (RotL64(aOrbiterG, 5U) ^ aOrbiterF);
            aIngress = aIngress + RotL64(aOrbiterJ, 21U);
            aIngress = TwistMix64::DiffuseA((aIngress + aScatter));
            //
            aWandererA = aWandererA + ((RotL64(aIngress, 23U) + RotL64(aOrbiterK, 13U)) + aOrbiterI);
            aWandererK = aWandererK ^ ((RotL64(aScatter, 57U) + RotL64(aOrbiterE, 5U)) + aOrbiterJ);
            aWandererC = aWandererC + (((RotL64(aPrevious, 47U) + RotL64(aOrbiterG, 29U)) + aOrbiterF) + RotL64(aCarry, 5U));
            aWandererJ = aWandererJ ^ (((RotL64(aCross, 29U) + aOrbiterE) + RotL64(aOrbiterK, 39U)) + aKeyRotateWandererUpdateSaltA[((aIndex + 5U)) & S_SALT1]);
            aWandererF = aWandererF + (((RotL64(aIngress, 41U) + aOrbiterI) + RotL64(aOrbiterG, 60U)) + aKeyRotateWandererUpdateSaltB[((aIndex + 17U)) & S_SALT1]);
            aWandererG = aWandererG ^ ((RotL64(aScatter, 12U) + aOrbiterA) + RotL64(aOrbiterJ, 21U));
            aWandererB = aWandererB + (((RotL64(aCross, 35U) + RotL64(aOrbiterE, 51U)) + aOrbiterI) + RotL64(aCarry, 21U));
