            aWandererI = aWandererI ^ (((RotL64(aIngress, 29U) + RotL64(aOrbiterD, 41U)) + aOrbiterG) + aKeyRotateWandererUpdateSaltE[(((31U - aIndex) + 23U)) & S_SALT1]);
            aWandererB = aWandererB + ((RotL64(aScatter, 54U) + RotL64(aOrbiterE, 26U)) + aOrbiterJ);
            aWandererJ = aWandererJ ^ ((RotL64(aCross, 37U) + aOrbiterF) + RotL64(aOrbiterG, 13U));
