            aCross = (RotL64(aFuseLaneB[((S_BLOCK1 - aIndex + 32595U)) & S_BLOCK1], 51U) ^ RotL64(aSoilLaneA[((S_BLOCK1 - aIndex + 27268U)) & S_BLOCK1], 11U));
