            //
            aOrbiterK = (aWandererE + RotL64(aCross, 53U)) + 0xB9425DCC7E17E8BBULL;
            aOrbiterB = (aWandererD + RotL64(aPrevious, 50U)) + 0x31EE15205AE514D9ULL;
            aOrbiterA = ((aWandererK + RotL64(aScatter, 29U)) + 0x8CDA3C5E1B50A842ULL) + aKeyRotateOrbiterAssignSaltB[((aIndex + 29U)) & S_SALT1];
            aOrbiterD = (aWandererB + RotL64(aIngress, 13U)) + 0x4620BC9E85237E69ULL;
            aOrbiterG = (((aWandererI + RotL64(aPrevious, 39U)) + RotL64(aCarry, 21U)) + 0x5097605D8AB25AB6ULL) + aKeyRotateOrbiterAssignSaltE[((aIndex + 21U)) & S_SALT1];
            aOrbiterJ = (aWandererH + RotL64(aIngress, 37U)) + 0x5B978FE0D36B38F5ULL;
            aOrbiterE = (aWandererA + RotL64(aCross, 27U)) + 0x9CC2862CC3F9FDF9ULL;
