            //
            aOrbiterD = ((aOrbiterD + aOrbiterA) + 0xA8E52CC62958A52BULL) + aKeyRotateOrbiterUpdateSaltB[(((31U - aIndex) + 16U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterD) ^ 0xB312A32A39341B35ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x6289A841D7A2044BULL), 5U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterJ) + 0x4B566585BA3E9C44ULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterA) ^ 0x63D596F1584115B2ULL) ^ aKeyRotateOrbiterUpdateSaltF[((aIndex + 26U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0xCB9467AEBCC16809ULL), 35U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterD) + 0x34CF9C057ADB9856ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterB) ^ 0x770C057EC62C2B8CULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x8911651A738F1B0FULL), 29U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterF) + 0xD25CD18654410C84ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterC) ^ 0x91D926242389B9C7ULL;
            aOrbiterK = RotL64((aOrbiterK * 0xA0E5C0E4F80BAA31ULL), 51U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterE) + 0xC1A89041C93E406AULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterG) ^ 0x88535249A090FD41ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x84E5C0E08CE979BFULL), 39U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterH) + 0xBB0CC36DCD02745EULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterE) ^ 0x103A9AEA63F6948EULL) ^ aKeyRotateOrbiterUpdateSaltA[(((31U - aIndex) + 6U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0x1570BBD8A89F1905ULL), 27U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterK) + 0x0E1D5DEFB6C80EE5ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterI) ^ 0x5AF0AC162F5B17E8ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x1F5AC8ACF831A95DULL), 19U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterG) + 0x16D2EDEA7E426576ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterJ) ^ 0x54CDE0E68F9DB3ADULL;
            aOrbiterH = RotL64((aOrbiterH * 0x59C9F2B5D38EB377ULL), 41U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterC) + 0x3C9AAB8A08B69769ULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterH) ^ 0x6487929AC0C559A2ULL) ^ aKeyRotateOrbiterUpdateSaltE[(((31U - aIndex) + 22U)) & S_SALT1];
