            aOrbiterE = (aOrbiterE + aOrbiterH) + 0x213D12451CAA47E2ULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterE) ^ 0x8E11506249B7AE17ULL) ^ aKeyRotateOrbiterUpdateSaltF[((aIndex + 29U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0x80AAB63C46F4A4D1ULL), 27U);
