            aIngress = (RotL64(aKineticLaneA[((aIndex + 8264U)) & S_BLOCK1], 22U) ^ RotL64(aAetherLaneC[((aIndex + 6046U)) & S_BLOCK1], 57U));
            aIngress ^= (RotL64(aWindLaneD[((aIndex + 9716U)) & S_BLOCK1], 5U) ^ RotL64(aWindLaneB[((aIndex + 7261U)) & S_BLOCK1], 39U));
            aIngress = TwistMix64::DiffuseB(aIngress);
            //
            aCross = (RotL64(aAetherLaneA[((S_BLOCK1 - aIndex + 5948U)) & S_BLOCK1], 48U) ^ RotL64(aAetherLaneD[((S_BLOCK1 - aIndex + 6063U)) & S_BLOCK1], 57U));
            aCross ^= (RotL64(aWindLaneA[((S_BLOCK1 - aIndex + 6154U)) & S_BLOCK1], 3U) ^ RotL64(aSoilLaneB[((aIndex + 9420U)) & S_BLOCK1], 21U));
