            aOrbiterK = ((aOrbiterK + aOrbiterD) + 0x4C9E7E670CB4FE9DULL) + aKeySpawnOrbiterUpdateSaltA[(((31U - aIndex) + 27U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterK) ^ 0xA99FBD65564FD8C8ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x30B45F0C3E937539ULL), 47U);
