            //
            aOrbiterA = ((aOrbiterA + aOrbiterB) + 0xFC27CD2DD17A4744ULL) + aKeySpawnOrbiterUpdateSaltF[((aIndex + 5U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterA) ^ 0x49CF80B3C467BE3EULL;
            aOrbiterG = RotL64((aOrbiterG * 0x4077738E86207BC5ULL), 51U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterH) + 0x4CA9AB48AFE639A5ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterF) ^ 0xABF116C5692842E9ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x6AD5AFDCE08D7E27ULL), 29U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterJ) + 0x36F0BEBE8897D9A9ULL) + aKeySpawnOrbiterUpdateSaltA[((aIndex + 13U)) & S_SALT1];
