            aOrbiterD = (aWandererG + RotL64(aScatter, 39U)) + 0x29EF25951970A7C5ULL;
            aOrbiterF = (((aWandererK + RotL64(aIngress, 18U)) + RotL64(aCarry, 23U)) + 0xF051936C46EB4979ULL) + aKeySpawnOrbiterAssignSaltA[((aIndex + 21U)) & S_SALT1];
            aOrbiterB = (aWandererB + RotL64(aCross, 27U)) + 0x32BF84BACC5D9538ULL;
