            //
            aOrbiterE = (aOrbiterE + aOrbiterJ) + 0xF97DF6B3B1E1EF8BULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterE) ^ 0xD156192ACE8EFC72ULL) ^ aKeySpawnOrbiterUpdateSaltF[(((31U - aIndex) + 15U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0x78F4AE57A65089E7ULL), 21U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterI) + 0xD87C28CE5A4351EAULL;
