            //
            aOrbiterG = (aOrbiterG + aOrbiterF) + 0x79ECDEC173106987ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterG) ^ 0x3D9F4C43873B6FA4ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x2C2562F872BCB197ULL), 51U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterK) + 0x8F1912859E5A20E8ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterC) ^ 0xE5818F963BA370D4ULL;
            aOrbiterI = RotL64((aOrbiterI * 0xAD29E79BE0320965ULL), 29U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterE) + 0xE74E4389821110CBULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterJ) ^ 0x11871156DEBA33B4ULL;
            aOrbiterF = RotL64((aOrbiterF * 0xB5D4CD1F7B4EB8C7ULL), 41U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterD) + 0x41335C83328AE6B8ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterE) ^ 0xE6D50CCA4B409863ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x9C1EA59EFACCF1F1ULL), 35U);
